#!/usr/bin/env python3
"""Read and verify a workbook generated by internal/testgen with openpyxl."""

import datetime
import sys

from openpyxl import load_workbook


def main() -> int:
    if len(sys.argv) != 2:
        raise SystemExit("usage: check_openpyxl.py <workbook.xlsx>")

    workbook = load_workbook(sys.argv[1], data_only=False)
    assert workbook.sheetnames == ["Data", "Summary"], workbook.sheetnames

    data = workbook["Data"]
    assert data["A1"].value == "Name"
    assert data["A2"].value == "Widget & <1>"
    assert data["A3"].value == "Widget & <2>"
    assert data["A2"].hyperlink is not None
    assert data["A2"].hyperlink.target == "https://example.com"

    assert abs(float(data["B2"].value) - 1.25) < 1e-9
    assert abs(float(data["B3"].value) - 2.25) < 1e-9
    assert data["B2"].number_format == "#,##0.00"
    assert data["B2"].font.bold is True
    assert data["B2"].alignment.horizontal == "center"

    assert data["C2"].value == datetime.datetime(2024, 1, 2, 3, 4, 5)
    assert data["D2"].value is True
    assert data["D3"].value is False

    assert data.freeze_panes == "A2", data.freeze_panes
    assert data.auto_filter.ref == "A1:D3", data.auto_filter.ref
    merged = {str(item) for item in data.merged_cells.ranges}
    assert "A4:B4" in merged, merged

    summary = workbook["Summary"]
    assert summary["A1"].value == "total"
    assert int(summary["B1"].value) == 42
    assert summary["C1"].value is True
    assert summary["D1"].value is None
    assert summary["E1"].value == "=SUM(B1:B2)", summary["E1"].value
    print("openpyxl interoperability check passed")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
